package vn.edu.fpt.seal.modules.audit.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import vn.edu.fpt.seal.common.enums.AuditAction; import vn.edu.fpt.seal.modules.incident.entity.IncidentReport; import vn.edu.fpt.seal.modules.team.entity.Team; import vn.edu.fpt.seal.modules.user.entity.User; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="audit_logs") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class AuditLog{ @Id @GeneratedValue @Column(name="id",updatable=false,nullable=false,columnDefinition="uuid") private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="team_id") private Team team; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="incident_id") private IncidentReport incident; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(name="action",nullable=false,columnDefinition="audit_action") private AuditAction action; @Column(name="target_type",nullable=false,length=100) private String targetType; @Column(name="target_id",nullable=false,columnDefinition="uuid") private UUID targetId; @Column(name="old_value",columnDefinition="text") private String oldValue; @Column(name="new_value",columnDefinition="text") private String newValue; @Column(name="details",columnDefinition="text") private String details; @CreationTimestamp @Column(name="occurred_at",nullable=false,updatable=false) private LocalDateTime occurredAt; }
